 const add=(type,name,x,y,rest={})=>objects.push({id:uid(),type,name,x,y,rotation:0,...rest});
 add('sofa','Three-seat sofa',448,325,{width:252,height:108,rotation:0});add('table','Coffee table',455,470,{width:144,height:72});add('table','Side table',735,270,{width:60,height:60});
 add('actor','Alex',500,590,{color:'#cf7d96'});add('actor','Jamie',695,415,{color:'#a094cc',rotation:155});
 add('camera','A · Wide master',405,675,{rotation:-40,fov:ScenicModel.cameraView({lens:35}).fov,lens:35,notes:'Establish the distance between Alex and Jamie. Hold the frame as the conversation settles.',shot:'Wide',height:'Eye level'});
 add('camera','B · Jamie close-up',730,660,{rotation:-95,fov:ScenicModel.cameraView({lens:85}).fov,lens:85,notes:'Stay on Jamie through the pause. Keep the practical soft in the background.',shot:'Close-up',height:'Eye level'});
