const scene=()=>doc.scenes.find(s=>s.id===doc.active)||doc.scenes[0];
const object=()=>scene().objects.find(o=>o.id===selected);
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2800);}
function invalidate(){dirty=true;}
function snapshot(){history.push(JSON.stringify(workspaceData()));if(history.length>60)history.shift();future=[];updateUndo();}
function save(){invalidate();$('save-state').innerHTML='<i></i> Saving…';clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{try{if(window.ScenicDesktop){await window.ScenicDesktop.request('saveProject',{project:JSON.stringify(workspaceData())});$('save-state').innerHTML='<i></i> Saved on this device';return;}if(!db)throw Error('Storage unavailable');const tx=db.transaction('projects','readwrite');tx.objectStore('projects').put(structuredClone(workspaceData()),'current');await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error);});$('save-state').innerHTML='<i></i> Saved on this device';}catch{$('save-state').textContent='Save a project backup';}},350);}
function refresh(){updateCanvasHint();renderTransport();ScenicModel.syncOpenings(scene().objects);renderProjects();renderScenes();renderLayers();renderInspector();renderShots();updateUndo();invalidate();$('scene-title').value=scene().title;$('project-name').value=doc.name;$('scene-number').textContent=String(doc.scenes.indexOf(scene())+1).padStart(2,'0');$('object-count').textContent=`${scene().objects.filter(o=>o.type!=='wallGroup').length} objects`;$('shot-count').textContent=scene().objects.filter(o=>o.type==='camera').length;}
function commit(){stopPlayback();ScenicModel.syncOpenings(scene().objects);save();refresh();renderLibrary();renderTransport();}
function undo(){if(!history.length)return;future.push(JSON.stringify(workspaceData()));loadWorkspace(JSON.parse(history.pop()));selected=null;selectedIds.clear();wallMultiSelect=false;wallStart=null;applyTheme();commit();}
function redo(){if(!future.length)return;history.push(JSON.stringify(workspaceData()));loadWorkspace(JSON.parse(future.pop()));selected=null;selectedIds.clear();wallMultiSelect=false;applyTheme();commit();}
function updateUndo(){const u=$('undo'),r=$('redo');if(u)u.disabled=!history.length;if(r)r.disabled=!future.length;}
function applyTheme(){document.documentElement.dataset.theme=doc.theme;$('theme').innerHTML=svg(doc.theme==='dark'?'sun':'moon');localStorage.setItem('scenic-theme',doc.theme);if($('settings-theme'))$('settings-theme').value=doc.theme;invalidate();}
function updateCanvasHint(){$('canvas-hint').textContent=wallMultiSelect?'Click walls to select · Group in Properties · Esc: cancel':selectionItems().length>1?'Drag selection to move · Shift: add/remove · Delete: remove selection':ScenicTransforms.aimable(object())&&!object().locked?(object().type==='actor'?'Circle: facing direction · Shift: 15° steps · Esc: cancel':'Circle: aim · Shift: 15° steps · Esc: cancel'):ScenicTransforms.supported(object())?'Squares: resize · Circle: rotate · Shift: proportions / 15° · Esc: cancel':'Drag empty map to select · Scroll to zoom · Space + drag to pan';}
