 document.querySelectorAll('[data-prop]').forEach(el=>{const begin=()=>{el.dataset.before=JSON.stringify(workspaceData());el.dataset.recorded='';};el.addEventListener('keydown',e=>{if(el.dataset.length&&e.key==='Enter'){e.preventDefault();el.blur();}});el.addEventListener('focus',begin);el.addEventListener('pointerdown',begin);el.addEventListener('input',()=>{if(el.dataset.length){el.setCustomValidity('');return;}if(el.dataset.before&&!el.dataset.recorded){history.push(el.dataset.before);future=[];el.dataset.recorded='1';updateUndo();}const prop=el.dataset.prop,target=['ambient','sceneNotes'].includes(prop)?scene():object();if(!target)return;let val=el.dataset.clock?(el.value?Number(el.value.split(':')[0])+Number(el.value.split(':')[1])/60:NaN):el.type==='checkbox'?el.checked:el.dataset.nullable&&el.value===''?null:['range','number'].includes(el.type)?Number(el.value):el.value;if(typeof val==='number'){if(!Number.isFinite(val))return;if(el.min!=='')val=Math.max(Number(el.min),val);if(el.max!=='')val=Math.min(Number(el.max),val);}if(el.dataset.distance)val*=UNITS_PER_INCH;const previous=target.type==='wallGroup'?{...target}:null;target[prop==='sceneNotes'?'notes':prop]=val;afterObjectChange(target,prop,previous);if(prop==='name')renderLayers();const output=$('out-'+prop);if(output)output.textContent=el.dataset.distance?formatLength(val):(el.dataset.time||el.dataset.clock)?timeLabel(val):val+(el.dataset.unit||'');renderShots();renderLayers();save();});el.addEventListener('change',()=>{if(el.dataset.length)updateLength(el);renderLayers();renderScenes();renderShots();});});
