function duplicate(){if(duplicateMultiSelection()||duplicateWallGroup())return;const o=object();if(!o)return;if(o.kind==='sun'){toast('Only one sun is allowed per scene');return;}snapshot();const copy=structuredClone(o);copy.id=uid();copy.name+=' copy';copy.x+=30;copy.y+=30;if(copy.type==='wall'){copy.x2+=30;copy.y2+=30;}if(ScenicModel.openingKind(copy)){delete copy.wallId;delete copy.wallT;ScenicModel.snapOpening(copy,scene().objects,36);}if(copy.marks)copy.marks.forEach(m=>{m.x+=30;m.y+=30;});scene().objects.push(copy);choose(copy.id);commit();}
