async function importImage(file,p){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Choose a PNG, JPG, or WebP image');return;}if(file.size>20*1024*1024){toast('Choose an image smaller than 20 MB');return;}try{const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file);});const img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=data;});const scale=Math.min(1,1200/img.width,1000/img.height);snapshot();const point=p||{x:(size.w/2-view.x)/view.z,y:(size.h/2-view.y)/view.z};const o={id:uid(),type:'image',name:file.name,x:point.x,y:point.y,width:img.width*scale,height:img.height*scale,rotation:0,opacity:65,locked:false,keepProportions:true,src:data};scene().objects.unshift(o);images.set(data,img);choose(o.id);showShots(false);setTool('select');commit();toast('Reference imported · adjust size and opacity in Properties');}catch{toast('This image could not be opened');}}
