window.addEventListener('keydown',e=>{if(e.defaultPrevented||['INPUT','TEXTAREA','SELECT','BUTTON'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;const mod=e.metaKey||e.ctrlKey,k=e.key.toLowerCase();if(mod&&k==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if(mod&&k==='d'){e.preventDefault();duplicate();return;}if(mod&&k==='s'){e.preventDefault();if(window.ScenicDesktop&&!e.shiftKey)window.scenicFlush().catch(e=>toast(e.message));else $('save-project').click();return;}if(mod&&k==='/'){e.preventDefault();openGuide();return;}if(e.code==='Space'){space=true;e.preventDefault();canvas.style.cursor='grab';return;}if(k==='escape'){if(drag){e.preventDefault();cancelDrag();return;}wallStart=null;choose(null);setTool('select');return;}if(k==='backspace'||k==='delete'){e.preventDefault();removeObject();return;}if(k==='0'){fit();return;}if(!mod&&({v:'select',b:'marquee',w:'wall',c:'camera',l:'light',a:'actor',h:'hand',s:'sofa',t:'table',i:'image'})[k]){if(k==='i')$('image-input').click();else setTool(({v:'select',b:'marquee',w:'wall',c:'camera',l:'light',a:'actor',h:'hand',s:'sofa',t:'table'})[k]);}if(k.startsWith('arrow')&&object()){e.preventDefault();const step=(e.shiftKey?12:1)*UNITS_PER_INCH,dx=k==='arrowleft'?-step:k==='arrowright'?step:0,dy=k==='arrowup'?-step:k==='arrowdown'?step:0;nudgeSelection(dx,dy);}});
