async function init(){setupWorkflow();setupTools();applyTheme();refresh();resize();fit();loop();if(window.ScenicDesktop){try{const stored=await window.ScenicDesktop.request('readProject');if(stored.project){const p=JSON.parse(stored.project);loadWorkspace(p);selected=null;selectedIds.clear();wallMultiSelect=false;applyTheme();refresh();fit();}window.scenicReady=true;if(stored.recovered)toast('Recovered your workspace from its previous autosave');$('save-state').innerHTML='<i></i> Saved on this device';}catch(e){$('save-state').textContent='Workspace could not be loaded';toast(e.message);}new ResizeObserver(resize).observe(wrap);return;}try{db=await new Promise((res,rej)=>{const request=indexedDB.open('scenic-workspace',1);request.onupgradeneeded=()=>request.result.createObjectStore('projects');request.onsuccess=()=>res(request.result);request.onerror=()=>rej(request.error);});const stored=await new Promise((res,rej)=>{const req=db.transaction('projects').objectStore('projects').get('current');req.onsuccess=()=>res(req.result);req.onerror=rej;});if(stored){loadWorkspace(stored);selected=null;selectedIds.clear();wallMultiSelect=false;applyTheme();refresh();fit();}else save();}catch{$('save-state').textContent='Use Save project for backups';}new ResizeObserver(resize).observe(wrap);}
